-- Quests linked to a dungeon (attunement, pre-quests, quests picked up outside / inside): what to show and why a quest is not available yet.
-- Data: Data/Quests.lua (generated by tools/gen_quests.py). Quest state comes from the client (completed, in the quest log).
local _, ns = ...

local function safe(fn, ...)
    if not fn then return nil end
    local ok, a = pcall(fn, ...)
    if ok then return a end
end

local function isDone(id) return safe(C_QuestLog and C_QuestLog.IsQuestFlaggedCompleted, id) == true end
local function isActive(id) return safe(C_QuestLog and C_QuestLog.IsOnQuest, id) == true end

-- the client's title when it has one (it knows the quests of this character), else the name in our data
function ns.QuestTitle(q)
    local t = safe(C_QuestLog and C_QuestLog.GetTitleForQuestID, q.id)
    if type(t) == "string" and t ~= "" then return t end
    return q.name or ("Quest " .. q.id)
end

local function playerFaction()
    local f = safe(UnitFactionGroup, "player")
    if f == "Horde" then return "H" end
    if f == "Alliance" then return "A" end
end

-- class quests (Data: class = bitmask, bit = 2^(classID - 1)): shown only to that class
local function classAllowed(q)
    if not q.class then return true end
        local ok, _, _, classID = pcall(UnitClass, "player")
    if not ok or type(classID) ~= "number" then return true end
    return math.floor(q.class / 2 ^ (classID - 1)) % 2 == 1
end

function ns.HasQuests(instanceID)
    local list = ns.QuestData and ns.QuestData[instanceID]
    return list ~= nil and #list > 0
end

-- Quest status: "done" | "active" (in the quest log) | "locked" (+ reason text) | "ready"
local function status(q, byID, implied)
    if isDone(q.id) or implied[q.id] then return "done" end
    if isActive(q.id) then return "active" end
    if q.prereq then
        local pre = byID[q.prereq]
        if not (isDone(q.prereq) or implied[q.prereq]) then
            return "locked", "Requires: " .. (pre and ns.QuestTitle(pre) or safe(C_QuestLog and C_QuestLog.GetTitleForQuestID, q.prereq) or ("quest " .. q.prereq))
        end
    end
    local lvl = safe(UnitLevel, "player")
    if q.min and type(lvl) == "number" and lvl < q.min then
        return "locked", "Requires level " .. q.min
    end
    return "ready"
end

-- Entries for the Quests list of an instance, in display order:
--   { kind = "quest", q, status, reason, attune }  or  { kind = "chain", name, steps = {entries}, current, done, total, status, reason, attune }
-- Quests of the other faction are left out. Returns list, counts (open = not completed, done).
function ns.GetQuestEntries(instanceID)
    local data = ns.QuestData and ns.QuestData[instanceID]
    if not data then return nil end
    local faction = playerFaction()
    -- a quest is also done when a quest that needs it is done (the client may not flag early chain steps, e.g. when the chain was joined later)
    local all, implied = {}, {}
    for _, q in ipairs(data) do all[q.id] = q end
    for _, q in ipairs(data) do
        if isDone(q.id) then
            local p, n = q.prereq, 0
            while p and all[p] and n < 50 do implied[p] = true; p = all[p].prereq; n = n + 1 end
        end
    end
    local byID, quests = {}, {}
    for _, q in ipairs(data) do
        if not (faction and q.faction and q.faction ~= faction) and classAllowed(q) then
            byID[q.id] = q
            quests[#quests + 1] = q
        end
    end
    local chains, order, out = {}, {}, {}
    for _, q in ipairs(quests) do
        local e = { kind = "quest", q = q, attune = q.where == "attune" }
        e.status, e.reason = status(q, byID, implied)
        if q.prereq then
            local pre = byID[q.prereq] or all[q.prereq]
            local t = pre and ns.QuestTitle(pre) or safe(C_QuestLog and C_QuestLog.GetTitleForQuestID, q.prereq) or ("quest " .. q.prereq)
            e.pre = { title = t, done = isDone(q.prereq) or implied[q.prereq] == true }
        end
        if q.chain then
            local c = chains[q.chain]
            if not c then
                c = { kind = "chain", name = q.chain, steps = {} }
                chains[q.chain] = c
                order[#order + 1] = c
            end
            c.steps[#c.steps + 1] = e
        else
            out[#out + 1] = e
        end
    end
    for _, c in ipairs(order) do
        if #c.steps == 1 then
            out[#out + 1] = c.steps[1] -- a "chain" with a single visible step is just a quest
        else
            table.sort(c.steps, function(a, b) return (a.q.step or 99) < (b.q.step or 99) end)
            c.total, c.done = #c.steps, 0
            for _, s in ipairs(c.steps) do
                if s.status == "done" then c.done = c.done + 1 end
                if s.attune then c.attune = true end
            end
            for i, s in ipairs(c.steps) do
                s.index = i
                if s.status ~= "done" and not c.current then c.current = s end
            end
            if c.current then
                c.status, c.reason = c.current.status, c.current.reason
            else
                c.status = "done"
            end
            c.min = c.steps[1].q.min
            out[#out + 1] = c
        end
    end
    local function group(e) return e.status == "done" and 3 or (e.status == "locked" and 2 or 1) end
    local function minLevel(e) return e.min or (e.q and e.q.min) or 0 end
    table.sort(out, function(a, b)
        local ga, gb = group(a), group(b)
        if ga ~= gb then return ga < gb end
        if (a.attune or false) ~= (b.attune or false) then return a.attune == true end
        if minLevel(a) ~= minLevel(b) then return minLevel(a) < minLevel(b) end
        local na = a.kind == "chain" and a.name or (a.q and a.q.name or "")
        local nb = b.kind == "chain" and b.name or (b.q and b.q.name or "")
        return na < nb
    end)
    local open, done = 0, 0
    for _, e in ipairs(out) do
        if e.status == "done" then done = done + 1 else open = open + 1 end
    end
    return out, { open = open, done = done }
end

local function where(q)
    if q.where == "inside" then
        return "Inside the dungeon" .. (q.giver and (": " .. q.giver) or "")
    elseif q.where == "item" then
        return "Started by an item" .. (q.giverZone and (" (" .. q.giverZone .. ")") or "")
    end
    local g = q.giver and (q.giver .. (q.giverZone and (", " .. q.giverZone) or "")) or q.giverZone
    return (q.where == "attune" and "Attunement: " or "Pick up: ") .. (g or "see the quest giver")
end
ns.QuestWhere = where

-- One line under the quest name: why it is locked, where to get it, or its state.
function ns.QuestSubText(e)
    if e.kind == "chain" then
        if e.status == "done" then return "Completed", "done" end
        local cur = e.current
        local head = format("Step %d of %d: %s", cur.index, e.total, ns.QuestTitle(cur.q))
        if e.status == "locked" then return head .. " - " .. (e.reason or ""), "locked" end
        if e.status == "active" then return head .. " - in your quest log", "active" end
        return head, "ready"
    end
    if e.status == "done" then return "Completed", "done" end
    if e.status == "active" then return "In your quest log", "active" end
    if e.status == "locked" then return e.reason or "Not available yet", "locked" end
    return where(e.q), "ready"
end

-- Lines for the tooltip / detail pane of an entry: a status line, then "Label: value" facts, then the chain.
local LABEL = "|cffffd100%s:|r "
-- "NPC - Zone (x, y)": coordinates are the position on the zone map, as shown in game
local function place(npc, zone, x, y)
    local where = zone
    if x and y then where = (zone and (zone .. " ") or "") .. format("(%.1f, %.1f)", x, y) end
    if npc and where then return npc .. " - " .. where end
    return npc or where
end

function ns.QuestDetailLines(e)
    local lines = {}
    local function add(s) lines[#lines + 1] = s end
    local function fact(label, value) if value and value ~= "" then add(format(LABEL, label) .. value) end end
    local function one(en)
        local q, st = en.q, en.status
        if st == "done" then add("|cff66ff66Completed|r")
        elseif st == "active" then add("|cffffd100In your quest log|r")
        elseif st == "locked" then add("|cffff9060" .. (en.reason or "Not available yet") .. "|r")
        else add("|cffffffffAvailable|r") end
        if q.where == "attune" then add("|cffffd100Gives the key / attunement for this dungeon|r") end
        fact("Level", q.level and tostring(q.level))
        fact("Requires level", q.min and tostring(q.min))
        if q.where == "inside" then
            fact("Starts", place(q.giver, "inside the dungeon"))
        elseif q.where == "item" then
            fact("Starts", "an item" .. (q.giverZone and (": " .. q.giverZone) or "") .. (q.giver and (" (" .. q.giver .. ")") or ""))
        else
            fact("Starts", place(q.giver, q.giverZone, q.gx, q.gy))
        end
        fact("Ends", place(q.turnin, q.turninZone, q.tx, q.ty))
        if en.pre then
            fact("Requires", en.pre.title .. (en.pre.done and " |cff66ff66(done)|r" or ""))
        end
    end
    if e.kind == "chain" then
        add(format("|cffffd100Chain:|r %s - %d of %d done", e.name, e.done, e.total))
        for _, s in ipairs(e.steps) do
            local mark = s.status == "done" and " |cff66ff66(done)|r" or (s == e.current and " |cffffd100<- next|r" or "")
            add(format("  %d. %s%s", s.index, ns.QuestTitle(s.q), mark))
        end
        if e.current then
            add(" ")
            add("|cffffd100Next step:|r " .. ns.QuestTitle(e.current.q))
            one(e.current)
        end
    else
        one(e)
    end
    return lines
end
